// Recebe o CSV cru do nó HTTP Request e devolve a lista de investimentos.
// O nó HTTP pode entregar o conteúdo em "data", em "body" ou no próprio json,
// dependendo da versão — por isso os três fallbacks.
const csvCru = $json.data ?? $json.body ?? $json;
const texto = (typeof csvCru === "string") ? csvCru : JSON.stringify(csvCru);

const linhas = texto.split(/\r?\n/).map(l => l.trim()).filter(Boolean);

if (linhas.length < 2) {
  throw new Error("CSV vazio ou sem linhas de dados. Confira a URL do HTTP Request.");
}

const cabecalho = linhas[0].split(",").map(h => h.trim());

const investimentos = linhas.slice(1).map(linha => {
  const colunas = linha.split(",").map(c => c.trim());
  const obj = {};
  cabecalho.forEach((h, i) => { obj[h] = colunas[i] ?? ""; });

  // "1000" e "R$ 1.000" viram 1000. Sem isso a comparação com o saldo é texto
  // contra número e falha em silêncio.
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// Cruza os clientes recebidos pelo Webhook com as opções de investimento do CSV
// e monta a mensagem de cada um. Mensagens ESTÁTICAS, por template — é o que o
// MVP do desafio pede. A versão com LLM é o desafio extra.

const entrada = $input.first().json;

const clientes = entrada.body?.clientes ?? entrada.clientes ?? [];
const investimentos = entrada.investimentos ?? [];

if (clientes.length === 0) {
  throw new Error("Nenhum cliente recebido. Confira se o POST do RPA chegou no Webhook.");
}
if (investimentos.length === 0) {
  throw new Error("Nenhum investimento carregado. Confira o HTTP Request e o nó de parse do CSV.");
}

// "R$ 12.500,00" -> 12500
// O ponto é separador de milhar e a vírgula é decimal: trocar na ordem errada
// transforma 12.500,00 em 12,5 e quebra toda a comparação.
function saldoParaNumero(texto) {
  if (typeof texto === "number") return texto;
  const limpo = String(texto ?? "")
    .replace(/[^\d.,-]/g, "")
    .replace(/\./g, "")
    .replace(",", ".");
  const n = Number(limpo);
  return Number.isFinite(n) ? n : 0;
}

function chavePerfil(p) {
  return String(p ?? "")
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "");
}

function moeda(n) {
  return n.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
}

function montarMensagens(cliente, produto, motivo) {
  const { nome, perfil } = cliente;
  const saldo = cliente.saldo_texto;

  if (motivo === "saldo_insuficiente") {
    return [
      `Olá ${nome}! Pelo seu perfil (${perfil}), uma boa porta de entrada é **${produto.produto}**, que começa em ${moeda(produto.minimo)}. Seu saldo hoje é de ${saldo} — falta pouco para chegar lá. Rentabilidade: ${produto.rentabilidade}.`,
      `Oi ${nome}! Separamos **${produto.produto}** como próximo passo para o perfil ${perfil}. A aplicação mínima é ${moeda(produto.minimo)} e seu saldo atual é ${saldo}. Rentabilidade: ${produto.rentabilidade}.`,
      `${nome}, indo direto ao ponto: a opção mais acessível do perfil ${perfil} é **${produto.produto}**, a partir de ${moeda(produto.minimo)}. Com ${saldo}, vale montar um plano para alcançar esse valor. Rentabilidade: ${produto.rentabilidade}.`,
    ];
  }

  if (motivo === "perfil_sem_produto") {
    return [
      `Olá ${nome}! Ainda não temos opção cadastrada para o perfil ${perfil}. Um especialista vai entrar em contato.`,
    ];
  }

  return [
    `Olá ${nome}! Pelo seu perfil (${perfil}), uma boa opção é **${produto.produto}** (mínimo ${moeda(produto.minimo)}). Com seu saldo atual (${saldo}), você já consegue investir. Rentabilidade: ${produto.rentabilidade}.`,
    `Oi ${nome}! Recomendação para perfil ${perfil}: **${produto.produto}** (mínimo ${moeda(produto.minimo)}). Seu saldo (${saldo}) já atende o mínimo. Rentabilidade: ${produto.rentabilidade}.`,
    `${nome}, indo direto ao ponto: para o perfil ${perfil}, **${produto.produto}** (mínimo ${moeda(produto.minimo)}). Você tem ${saldo}, então já dá para aplicar. Rentabilidade: ${produto.rentabilidade}.`,
  ];
}

// Escolhe sempre a primeira variação. Fica determinístico: rodar duas vezes
// com a mesma entrada produz a mesma saída, o que torna o fluxo testável.
function escolher(mensagens) {
  return mensagens[0];
}

const resultados = clientes.map((c) => {
  const perfil = c.perfil;
  const saldoNum = saldoParaNumero(c.saldo);

  const doPerfil = investimentos.filter(i => chavePerfil(i.perfil) === chavePerfil(perfil));
  const acessiveis = doPerfil.filter(i => saldoNum >= Number(i.minimo || 0));

  let escolhido = null;
  let motivo = "";

  if (doPerfil.length === 0) {
    motivo = "perfil_sem_produto";
  } else if (acessiveis.length > 0) {
    // Entre os que o saldo alcança, o de maior aplicação mínima — é o mais
    // completo da faixa, e o cliente já tem dinheiro para ele.
    escolhido = acessiveis.reduce((a, b) => (Number(b.minimo) > Number(a.minimo) ? b : a));
    motivo = "saldo_ok";
  } else {
    // Nenhum alcançado: sugere o de menor entrada, como meta.
    escolhido = doPerfil.reduce((a, b) => (Number(b.minimo) < Number(a.minimo) ? b : a));
    motivo = "saldo_insuficiente";
  }

  const base = { nome: c.nome, perfil, saldo_texto: c.saldo };
  const mensagens = montarMensagens(base, escolhido ?? {}, motivo);

  return {
    nome: c.nome,
    email: c.email,
    perfil,
    saldo_texto: c.saldo,
    saldo_num: saldoNum,
    recomendacao: escolhido,
    motivo,
    mensagens,
    mensagem_escolhida: escolher(mensagens),
  };
});

return [{
  json: {
    ok: true,
    total_clientes: resultados.length,
    total_investimentos: investimentos.length,
    resumo_por_motivo: resultados.reduce((acc, r) => {
      acc[r.motivo] = (acc[r.motivo] || 0) + 1;
      return acc;
    }, {}),
    resultados,
  },
}];
